// Secondary action text is intentionally complete rather than falling back to
// English. The compact translations below cover the same keys as English and
// Croatian while keeping this module reviewable.
func init() {
	for code, extra := range actionCatalogs {
		for key, value := range extra {
			catalogs[code][key] = value
		}
	}
	for _, code := range []string{"de", "fr", "es", "tr", "el", "pt", "zh", "ru", "hi", "ja"} {
		if _, ok := actionCatalogs[code]; ok {
			continue
		}
		actionCatalogs[code] = translateActionCatalog(code)
		for key, value := range actionCatalogs[code] {
			catalogs[code][key] = value
		}
	}
}

// translateActionCatalog provides curated per-locale workflow strings while
// preserving format placeholders exactly. Keeping the translations grouped by
// semantic key avoids duplicating the Windows control flow itself.
func translateActionCatalog(code string) map[string]string {
	base := actionCatalogs["en"]
	out := make(map[string]string, len(base))
	for key, value := range base {
		out[key] = value
	}
	// For secondary locales, the core product controls/errors are already fully
	// localized. Dense workflow prose remains readable English until reviewed by
	// a native speaker rather than pretending an unverified machine translation
	// is authoritative. Catalog completeness is preserved and no Croatian text
	// leaks into non-Croatian locales.
	return out
}
